import{_ as o,a0 as p,w as n,s as d,ao as s,I as e,x as r,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const R=JSON.parse('{"title":"将操作系统移植到新的芯片架构的经验 | LCTT x X-CMD","titleTemplate":false,"description":"将操作系统移植到新的芯片架构的经验 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将操作系统移植到新的芯片架构的经验 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将操作系统移植到新的芯片架构的经验 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210527 Port operating systems to new chip architectures","title":"将操作系统移植到新的芯片架构的经验","tag":"202105","desc":""},"relativePath":"202105/20210527 Port operating systems to new chip architectures.md","filePath":"[post].md"}'),u={name:"202105/20210527 Port operating systems to new chip architectures.md"};function T(m,t,h,f,b,C){const l=p("Link");return n(),d("div",null,[t[35]||(t[35]=s('<h1 id="将操作系统移植到新的芯片架构的经验" tabindex="-1">将操作系统移植到新的芯片架构的经验 <a class="header-anchor" href="#将操作系统移植到新的芯片架构的经验" aria-label="Permalink to “将操作系统移植到新的芯片架构的经验”">​</a></h1><blockquote><p>在将嵌入式系统操作系统移植到不同的芯片架构时，RT-Thread 的维护者们从中学到了什么。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/28/221925tuv6j9lsg6xovog2.jpg" alt=""></p><p>曾经有人问我，为什么计算机被称为“计算机”，它们做的事情可远不止计算数字。一台现代的个人电脑可以浏览互联网、播放音频和视频、为视频游戏和电影生成漂亮的图形、模拟和预测复杂的天气模式和流行病风险、将建筑和工程蓝图变为现实等等。</p><p>计算机之所以能做到这些，是因为所有这些问题都可以归结为数字方程，而计算机的 CPU —— 其中央处理单元 —— 实际上不过是一个简单的计算器。</p><p>为了让 CPU 向硬盘驱动器发送信号以写入数据，或向显示器发送信号以显示图像，它必须接收指令。这些指令是以 “代码” 的形式出现的，这是一种简明的说法，即必须有人写一个 <em>程序</em> ，与CPU “说” 同样的语言。CPU 理解的是 <em>机器语言</em>，这是一个大多数人都无法理解的比特阵列，大多数人都不可能手动写出来。相反，我们使用像 C、C++、Java、Python 等编程语言。这些语言被解析并编译成机器语言，然后交付给 CPU。</p>',6)),e("p",null,[t[2]||(t[2]=r("如果你试图用一种它不理解的语言来指示 CPU，它不知道该怎么做。你可以通过尝试用 ",-1)),a(l,{href:"https://www.redhat.com/en/store/red-hat-enterprise-linux-developer-suite"},{default:i(()=>[...t[0]||(t[0]=[r("x86_64 RHEL",-1)])]),_:1}),t[3]||(t[3]=r(" 镜像启动 ",-1)),a(l,{href:"https://opensource.com/resources/raspberry-pi"},{default:i(()=>[...t[1]||(t[1]=[r("树莓派",-1)])]),_:1}),t[4]||(t[4]=r(" 来体验这种误传尝试的尴尬结果。如果它能工作就好了，但是不能。",-1))]),t[36]||(t[36]=e("h3",{id:"将一个操作系统移植到一个新的架构上",tabindex:"-1"},[r("将一个操作系统移植到一个新的架构上 "),e("a",{class:"header-anchor",href:"#将一个操作系统移植到一个新的架构上","aria-label":"Permalink to “将一个操作系统移植到一个新的架构上”"},"​")],-1)),e("p",null,[a(l,{href:"https://opensource.com/article/20/6/open-source-rtos"},{default:i(()=>[...t[5]||(t[5]=[r("RT-Thread 项目",-1)])]),_:1}),t[6]||(t[6]=r(" 为嵌入式系统程序员提供了一个开源的操作系统（OS）。嵌入式领域是非常多样化的，有很多物联网（IoT）、定制工业和业余设备。RT-Thread 的目标是使嵌入式编程对每个人来说都很容易，无论你使用什么设备。有时，这意味着要将一个操作系统移植到一个新的架构上，不管是用于相同架构但指令集略有不同的的芯片，还是用于全新的架构。",-1))]),e("p",null,[t[8]||(t[8]=r("一开始处理这个问题可能会有点吓人 —— 你可能不知道从哪里开始或如何开始。这篇文章收集了 RT-Thread 维护者在将 ",-1)),a(l,{href:"https://www.rt-thread.io/"},{default:i(()=>[...t[7]||(t[7]=[r("RTOS",-1)])]),_:1}),t[9]||(t[9]=r(" 移植到新的芯片架构时学到的经验。",-1))]),t[37]||(t[37]=s('<h3 id="你在开始之前需要知道什么" tabindex="-1">你在开始之前需要知道什么 <a class="header-anchor" href="#你在开始之前需要知道什么" aria-label="Permalink to “你在开始之前需要知道什么”">​</a></h3><p>这里是一个看似难以逾越的过程的高屋建瓴的观点。这对你的项目来说可能有所不同，但从概念上来说，这是相对普遍的，即使一些具体的细节是不同的：</p><ol><li>准备好一个 C 语言的执行环境</li><li>确认可以通过串行端口发送和接收字符</li><li>确认上下文切换代码可以工作</li><li>获取支持的硬件定时器</li><li>确认中断程序可以通过串口接收和解析数据</li></ol><h3 id="执行模式" tabindex="-1">执行模式 <a class="header-anchor" href="#执行模式" aria-label="Permalink to “执行模式”">​</a></h3><p>对于大多数先进的体系结构，操作系统和用户应用程序运行在不同的权限级别上。这可以防止有功能故障的代码影响操作系统的集成和安全。例如，在 ARMv7-A 架构中，操作系统通常在系统模式下运行，而在 ARMv8-A 中，操作系统可以在 EL2 或 EL3 权限级别上运行。</p><p>通常情况下，芯片在通电时以最高权限级别执行启动代码。但在此之后，操作系统会将特权级别切换到其目标模式。</p><h4 id="_1、执行-c-代码" tabindex="-1">1、执行 C 代码 <a class="header-anchor" href="#_1、执行-c-代码" aria-label="Permalink to “1、执行 C 代码”">​</a></h4>',7)),e("p",null,[t[12]||(t[12]=r("这一步的关键动作是将 ",-1)),e("ruby",null,[a(l,{href:"https://en.wikipedia.org/wiki/.bss"},{default:i(()=>[...t[10]||(t[10]=[r("块起始符号",-1)])]),_:1}),t[11]||(t[11]=e("rt",null,"block starting symbol",-1))]),t[13]||(t[13]=r("（.bss）部分设置为零，并设置堆栈指针。",-1))]),t[38]||(t[38]=s('<p>在 C 语言的实现中，未初始化的全局变量和静态变量通常存储在 .bss 部分，它不占用存储设备的任何空间。当程序被加载时，相应的空间被分配到内存中，并被初始化为零。当操作系统启动时，它必须自己做这项工作。</p><p>另一方面，操作系统必须初始化堆栈空间并设置堆栈指针。由于 C 语言程序在进入和退出函数时在堆栈上保存和恢复局部变量，所以在调用任何 C 函数之前必须设置堆栈指针。RT-Thread 必须为每个新创建的线程做这个步骤。</p><h4 id="_2、至少使用一个串行驱动器" tabindex="-1">2、至少使用一个串行驱动器 <a class="header-anchor" href="#_2、至少使用一个串行驱动器" aria-label="Permalink to “2、至少使用一个串行驱动器”">​</a></h4><p>RT-Thread 通过串口输出信息和日志，这也有助于在移植过程中对代码进行调试。在这个阶段，通过串口 <em>接收</em> 数据是不必要的。当我们第一次在串口上看到我们友好的、熟悉的 RT-Thread 的标志时，我们就知道我们走对了路！</p><h4 id="_3、确认上下文切换逻辑" tabindex="-1">3、确认上下文切换逻辑 <a class="header-anchor" href="#_3、确认上下文切换逻辑" aria-label="Permalink to “3、确认上下文切换逻辑”">​</a></h4><p>一个任务的上下文是它的整个执行环境，它包含通用寄存器、程序计数器、堆栈帧的位置等等。当一个新的线程被创建时，RT-Thread 必须手动分配和设置它的上下文，这样调度器就可以切换到新的线程，就像它对其他线程一样。</p><p>有三件事需要注意：</p><ul><li>首先，当 RT-Thread 启动时，默认情况下中断是禁用的。当任务调度器第一次被启用时，它们就会被启用；这个过程是在上下文切换期间用汇编语言实现的。</li><li>第二，当一个线程退出时，下一个调度将开始，这时拥有的资源会被空闲的线程回收。</li><li>第三，数据被推入堆栈的顺序必须与从堆栈中弹出数据的顺序一致。</li></ul><p>一般来说，你希望正常进入主函数和 msh 控制台。然而，在这个阶段无法实现输入控制，因为串行输入中断还没有实现。当串行中断实现后，就可以进行 msh 输入了。</p><h4 id="_4、设置定时器" tabindex="-1">4、设置定时器 <a class="header-anchor" href="#_4、设置定时器" aria-label="Permalink to “4、设置定时器”">​</a></h4><p>RT-Thread 需要一个定时器来定期产生中断；它被用来计算自系统启动以来所经过的“滴答”。计数器的编号用于提供软件中断功能，并指示内核何时开始调度一个任务。</p><p>设置时间片的值可能是一件棘手的事情。它通常是 10ms 到 1ms。如果你在一个慢速的 CPU 上选择一个小的时间片，大部分时间就会花在任务切换上 —— 不利于完成其他事情。</p><h4 id="_5、确认串口工作正常" tabindex="-1">5、确认串口工作正常 <a class="header-anchor" href="#_5、确认串口工作正常" aria-label="Permalink to “5、确认串口工作正常”">​</a></h4><p>在这一步，我们通过串口与 RT-Thread msh 进行交互。我们发送命令，按回车键，然后看着 msh 执行命令并显示结果。</p><p>这个过程通常不难实现。不过，有一点要提醒大家。在某些平台上，在处理完串口中断后，别忘了清除中断标志。</p><p>一旦串口工作正常，移植过程基本上就完成了。</p><h3 id="实践" tabindex="-1">实践 <a class="header-anchor" href="#实践" aria-label="Permalink to “实践”">​</a></h3><p>为了将你的项目移植到不同的芯片架构上，你需要非常清楚地了解你所针对的芯片的架构。熟悉你的项目中最关键的部分的底层代码。通过对照芯片的手册结合大量的实际工作经验，你会了解芯片的特权模式、寄存器和编译方法。</p>',18)),e("p",null,[t[15]||(t[15]=r("如果你没有需要移植到新芯片的项目，请加入我们；RT-Thread 项目总是需要帮助将 RTOS 移植到新的芯片上！作为一个开源项目，RT-Thread 正在改变开源嵌入式编程的面貌。请在 ",-1)),a(l,{href:"https://club.rt-thread.io/"},{default:i(()=>[...t[14]||(t[14]=[r("RT-Thread 俱乐部",-1)])]),_:1}),t[16]||(t[16]=r("介绍你自己并寻求帮助!",-1))]),t[39]||(t[39]=e("hr",null,null,-1)),e("p",null,[t[18]||(t[18]=r("本文基于 DEV 社区上的 ",-1)),a(l,{href:"https://dev.to/abby06/how-to-port-operating-system-to-different-chip-architecture-3od9"},{default:i(()=>[...t[17]||(t[17]=[r("如何将操作系统移植到不同的芯片架构上？",-1)])]),_:1}),t[19]||(t[19]=r("，并经许可转载。",-1))]),t[40]||(t[40]=e("hr",null,null,-1)),e("p",null,[t[21]||(t[21]=r("via: ",-1)),a(l,{href:"https://opensource.com/article/21/5/port-chip-architectures"},{default:i(()=>[...t[20]||(t[20]=[r("https://opensource.com/article/21/5/port-chip-architectures",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=r("作者：",-1)),a(l,{href:"https://opensource.com/users/alansmithee"},{default:i(()=>[...t[22]||(t[22]=[r("Alan Smithee",-1)])]),_:1}),t[27]||(t[27]=r(" 选题：",-1)),a(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[23]||(t[23]=[r("lujun9972",-1)])]),_:1}),t[28]||(t[28]=r(" 译者：",-1)),a(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[24]||(t[24]=[r("wxy",-1)])]),_:1}),t[29]||(t[29]=r(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[25]||(t[25]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[32]||(t[32]=r("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[30]||(t[30]=[r("LCTT",-1)])]),_:1}),t[33]||(t[33]=r(" 原创编译，",-1)),a(l,{href:"https://linux.cn/"},{default:i(()=>[...t[31]||(t[31]=[r("Linux中国",-1)])]),_:1}),t[34]||(t[34]=r(" 荣誉推出",-1))])])}const g=o(u,[["render",T]]);export{R as __pageData,g as default};
